sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_count;
uniform float amzp_scanType;
uniform float amzp_stripSize;
uniform float amzp_seed;
uniform float amzp_rate;
uniform float amzp_space;
uniform float amzp_quality;
uniform float amzp_scanOn;
uniform float amzp_scanAmp;
uniform float amzp_scanCh;
uniform float amzp_blockOn;
uniform float amzp_blockAmp;
uniform float amzp_blockCh;
uniform float amzp_offsetOn;
uniform float amzp_offsetAmp;
uniform float amzp_offsetCh;
uniform float amzp_rectOn;
uniform float amzp_rectAmp;
uniform float amzp_rectCh;
uniform float amzp_alphaMode;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float hs;
    float r1(float a, float b) { return fract(sin(a * 12.9898 + b * 78.233 + hs * 0.1731) * 43758.5453); }
    float4 srcPx(float2 px, float2 W) {
        float2 uv = px / W;
        uv.x = fract(uv.x);
        uv.y = clamp(uv.y, 0.0, 1.0);
        return amzTexture(0, l2s(float2(uv.x, 1.0 - uv.y)));
    }
    float3 toS(float3 c) {
        if (int(amzp_space) == 0) return c;
        return float3(dot(c, float3(0.299, 0.587, 0.114)), dot(c, float3(-0.169, -0.331, 0.5)) + 0.5, dot(c, float3(0.5, -0.419, -0.081)) + 0.5);
    }
    float3 fromS(float3 y) {
        if (int(amzp_space) == 0) return y;
        float u = y.y - 0.5, v = y.z - 0.5;
        return float3(y.x + 1.402 * v, y.x - 0.344 * u - 0.714 * v, y.x + 1.772 * u);
    }
    float3 chMask(int ch) { return ch == 1 ? float3(1.0, 0.0, 0.0) : (ch == 2 ? float3(0.0, 1.0, 0.0) : (ch == 3 ? float3(0.0, 0.0, 1.0) : float3(1.0))); }
    float3 unp(float4 c) { return c.a > 0.0001 ? c.rgb / c.a : float3(0.0); }
    void nmMain() {
        float2 W = layer;
        float2 px = float2(amzLayerNorm().x, 1.0 - amzLayerNorm().y) * W;
        hs = amzp_seed + (amzp_rate > 0.0 ? floor(time * amzp_rate) * 7.13 : 0.0);
        float n = clamp(floor(amzp_count + 0.5), 0.0, 48.0);
        float strip = max(amzp_stripSize, 2.0);
        float nStrips = max(floor(W.y / strip), 1.0);
        float4 orig = srcPx(px, W);
        float3 cS = toS(unp(orig));
        float alpha = orig.a;
        for (int i = 0; i < 48; i++) {
            float fi = float(i);
            if (fi >= n) break;
            float kind = floor(r1(fi, 1.0) * 4.0);
            float y0, y1;
            if (int(amzp_scanType) == 1) {
                float s = floor(r1(fi, 2.0) * nStrips);
                y0 = s * strip; y1 = y0 + strip;
            } else {
                float hgt = kind == 0.0 ? 1.0 + r1(fi, 3.0) * 4.0 : 6.0 + r1(fi, 3.0) * W.y * 0.18;
                y0 = r1(fi, 2.0) * W.y; y1 = y0 + hgt;
            }
            if (px.y < y0 || px.y >= y1) continue;
            if (kind == 0.0 && (amzp_scanOn>0.5)) {
                float x0 = r1(fi, 4.0) * W.x;
                if (px.x >= x0) {
                    float3 s = toS(unp(srcPx(float2(x0, px.y), W)));
                    s += (r1(fi, 5.0) - 0.5) * amzp_scanAmp;
                    cS = mix(cS, s, chMask(int(amzp_scanCh)));
                }
            } else if (kind == 1.0 && (amzp_blockOn>0.5)) {
                float bx0 = r1(fi, 4.0) * W.x, bx1 = bx0 + (0.1 + r1(fi, 6.0) * 0.4) * W.x;
                if (px.x >= bx0 && px.x < bx1) {
                    float2 b = floor(px / 16.0);
                    if (r1(b.x + fi * 3.1, b.y + 7.0) < amzp_blockAmp) {
                        float2 j = floor(float2(r1(b.x, b.y + fi), r1(b.y, b.x - fi)) * W / 16.0) * 16.0;
                        float2 q = j + mod(px, 16.0);
                        float3 s = toS(unp(srcPx(q, W)));
                        if (r1(b.x - fi, b.y) < 0.3) s = s.zxy;
                        cS = mix(cS, s, chMask(int(amzp_blockCh)));
                    }
                }
            } else if (kind == 2.0 && (amzp_offsetOn>0.5)) {
                float dx = (r1(fi, 4.0) * 2.0 - 1.0) * amzp_offsetAmp;
                float4 sp = srcPx(px - float2(dx, 0.0), W);
                cS = mix(cS, toS(unp(sp)), chMask(int(amzp_offsetCh)));
                if (int(amzp_offsetCh) == 0) alpha = sp.a;
            } else if (kind == 3.0 && (amzp_rectOn>0.5)) {
                float rx0 = r1(fi, 4.0) * W.x, rx1 = rx0 + (0.05 + r1(fi, 6.0) * 0.35) * W.x;
                if (px.x >= rx0 && px.x < rx1 && r1(floor(px.y / 4.0), fi) < 0.5 + amzp_rectAmp * 0.5) {
                    float2 d = (float2(r1(fi, 7.0), r1(fi, 8.0)) - 0.5) * W * amzp_rectAmp * 0.5;
                    float3 s = toS(unp(srcPx(px + d, W)));
                    s = mix(s, s.yzx, step(0.5, r1(fi, 9.0)));
                    s = mix(s, 1.0 - s, step(0.8, r1(fi, 10.0)) * amzp_rectAmp);
                    cS = mix(cS, s, chMask(int(amzp_rectCh)));
                }
            }
        }
        float q = clamp(amzp_quality, 0.0, 1.0);
        if (q < 0.999) {
            float2 b8 = (floor(px / 8.0) + 0.5) * 8.0;
            float3 m = toS(unp(srcPx(b8, W)));
            float step8 = mix(0.35, 0.01, q);
            float3 det = floor((cS - m) / step8 + 0.5) * step8;
            float3 comp = m + det;
            if (int(amzp_space) == 1) {
                float2 b16 = (floor(px / 16.0) + 0.5) * 16.0;
                comp.yz = mix(toS(unp(srcPx(b16, W))).yz, comp.yz, q);
            }
            cS = mix(comp, cS, q * q);
        }
        float3 col = clamp(fromS(cS), 0.0, 1.0);
        float a;
        if (int(amzp_alphaMode) == 1) a = 1.0;
        else if (int(amzp_alphaMode) == 2) a = orig.a;
        else a = max(alpha, orig.a * 0.0 + alpha);
        amzOutput = float4(col * a, a);
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
